#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-component-spec-vs-source.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-component-spec-vs-source — refuses drift between spec.yaml and source.
 *
 * @version 5
 * @updated 2026-06-06
 *
 * Components are discovered via the shared `_discover-components.mjs` helper
 * (path-agnostic: components/ui/, generic components/, and feature-located
 * <feature>/components/), NOT only src/components/ui/.
 *
 * For each atomic primitive at <srcRoot>/components/ui/<Name>/ checks:
 *
 *   1. Every `state-*` class string in any .tsx under the component folder
 *      AND under the corresponding shadcn baseline (if present) is declared in
 *      spec.yaml's `state_classes_consumed:` list.
 *
 *   2. Every `var(--*)` CSS variable in any .tsx under the component folder
 *      AND under the corresponding shadcn baseline is declared in spec.yaml's
 *      `tokens_consumed:` list.
 *
 * Anything in the spec list that's NOT in the source is also flagged
 * (over-claimed in the spec → stale).
 *
 * This catches the drift class that's silently passed before: source-code
 * changes that don't update the spec/design/usage docs. The verifier diffs
 * the two sources of truth and refuses any mismatch.
 *
 * Exclusions:
 *   - State classes used inside Tailwind variant tokens like
 *     `data-[state=open]:bg-...` are NOT counted (they're driven by data
 *     attributes, not state-* utility classes).
 *   - Tokens used only inside __stories__/ or __tests__/ folders are NOT
 *     counted (those are demo/test surfaces, not the primitive's API).
 *   - The shadcn baseline at packages/<pkg>/src/components/shadcn/<name>.tsx
 *     (lowercase) IS scanned, because the UI re-export's tokens are inherited
 *     from there.
 *
 * Usage:
 *   node verify-component-spec-vs-source.mjs <src-root>
 *
 * Exit 0 = drift-free. Non-zero = drift; surface specifics and refuse.
 */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { discoverComponents } from "./_discover-components.mjs";
import { applyExceptions } from "./_load-exceptions.mjs";

const RULE_ID = "verify-component-spec-vs-source";

const RED = "\x1b[31m";
const GREEN = "\x1b[32m";
const DIM = "\x1b[2m";
const RESET = "\x1b[0m";

const STATE_CLASS_RE = /\bstate-[a-z0-9-]+\b/g;
const TOKEN_RE = /var\(\s*(--[a-z0-9-]+)\s*[),]/gi;

function loadYaml() {
  try {
    const require = createRequire(process.cwd() + "/");
    return require("yaml");
  } catch {
    return null;
  }
}

function fail(msg) {
  process.stderr.write(`${RED}❌ verify-component-spec-vs-source:${RESET} ${msg}\n`);
  process.exit(1);
}
function ok(msg) {
  process.stdout.write(`${GREEN}✅ verify-component-spec-vs-source${RESET} — ${msg}\n`);
}

const srcRoot = (process.argv[2] || "src");
if (!srcRoot) {
  process.stderr.write("usage: verify-component-spec-vs-source.mjs <src-root>\n");
  process.exit(2);
}

// Broadened: discover components via the shared helper (components/ui, generic
// components/, and feature-located <feature>/components/), not only components/ui.
const componentRecords = discoverComponents(srcRoot);
if (componentRecords.length === 0) {
  ok(`no design-system components found under ${srcRoot} (components/ui, components/, or feature-located components/); nothing to verify.`);
  process.exit(0);
}

// shadcn baseline (atomic primitives re-export it). Feature-located components
// usually have no shadcn baseline — candidateBaselines just stays empty for them.
const shadcnRoot = path.join(srcRoot, "components", "shadcn");

const yaml = loadYaml();
if (!yaml) {
  fail("`yaml` package not installed — needed to parse spec.yaml");
}

const violations = [];

for (const rec of componentRecords) {
  const comp = rec.name;
  const compDir = rec.dir;
  const specPath = rec.specPath;
  if (!fs.existsSync(specPath)) continue;

  const specText = fs.readFileSync(specPath, "utf-8");
  let spec;
  try {
    spec = yaml.parse(specText);
  } catch (e) {
    violations.push(
      ...applyExceptions({
        dir: compDir,
        ruleId: RULE_ID,
        violations: [{ comp, kind: "spec_parse", msg: e.message }],
        rel: comp,
      }),
    );
    continue;
  }

  // Collect source .tsx files (exclude __stories__, __tests__, __specs__).
  const sourceFiles = [];
  for (const entry of walk(compDir)) {
    const rel = path.relative(compDir, entry);
    if (rel.split(path.sep).some((seg) => seg === "__stories__" || seg === "__tests__" || seg === "__specs__")) continue;
    // Include a co-located .css file (e.g. a portalled component whose chrome lives in
    // its own stylesheet, outside the .a11y-sidepanel token cascade) so its var(--*) +
    // state-* usage is reconciled against spec.yaml too.
    if (entry.endsWith(".tsx") || entry.endsWith(".ts") || entry.endsWith(".css")) {
      sourceFiles.push(entry);
    }
  }
  // Include the shadcn baseline declared in spec.baseline.installed_to (preferred),
  // or guess at the lowercased / dashed name (fallback).
  const candidateBaselines = [];
  if (spec.baseline?.installed_to) {
    const abs = path.resolve(String(spec.baseline.installed_to));
    if (fs.existsSync(abs)) candidateBaselines.push(abs);
  }
  if (fs.existsSync(shadcnRoot)) {
    const a = path.join(shadcnRoot, `${comp.toLowerCase()}.tsx`);
    if (fs.existsSync(a)) candidateBaselines.push(a);
    const b = path.join(
      shadcnRoot,
      `${comp.replace(/([A-Z])/g, "-$1").toLowerCase().replace(/^-/, "")}.tsx`,
    );
    if (fs.existsSync(b)) candidateBaselines.push(b);
  }
  for (const c of candidateBaselines) {
    if (!sourceFiles.includes(c)) sourceFiles.push(c);
  }
  // Crawl one level of LOCAL relative imports from each baseline, to follow
  // delegation chains (e.g. toggle-group.tsx imports toggleVariants from "./toggle").
  for (const start of [...candidateBaselines]) {
    const baseDir = path.dirname(start);
    const text = fs.readFileSync(start, "utf-8");
    const importRe = /from\s+["']\.\/(.+?)["']/g;
    for (const m of text.matchAll(importRe)) {
      for (const ext of [".tsx", ".ts"]) {
        const target = path.join(baseDir, m[1] + ext);
        if (fs.existsSync(target) && !sourceFiles.includes(target)) {
          sourceFiles.push(target);
        }
      }
    }
  }

  const sourceStateClasses = new Set();
  const sourceTokens = new Set();
  for (const f of sourceFiles) {
    let text = fs.readFileSync(f, "utf-8");
    // Strip import / re-export-from statements before scanning. An import path
    // like "../state-pill" (a kebab atomic folder) otherwise false-matches the
    // state-* class regex; module specifiers are never CSS state classes or tokens.
    text = text.replace(/^\s*import\b[\s\S]*?from\s*["'][^"']+["'];?\s*$/gm, "");
    text = text.replace(/^\s*export\b[^\n]*\bfrom\s*["'][^"']+["'];?\s*$/gm, "");
    for (const m of text.matchAll(STATE_CLASS_RE)) sourceStateClasses.add(m[0]);
    for (const m of text.matchAll(TOKEN_RE)) sourceTokens.add(m[1]);
  }

  const specStateClasses = new Set(
    (spec.state_classes_consumed ?? [])
      .filter((s) => typeof s === "string")
      .filter((s) => /^state-[a-z0-9-]+$/.test(s.trim()))
      .map((s) => s.trim()),
  );
  const specTokens = new Set(
    (spec.tokens_consumed ?? [])
      .filter((s) => typeof s === "string")
      // Only real `--token` entries participate in the diff; an "n/a — <reason>"
      // sentinel row (used by thin composers that delegate all chrome to a
      // consumed component, where verify-component-spec still wants a non-empty
      // block) is ignored — mirrors the state_classes_consumed filter above.
      .filter((s) => /^--[a-z0-9-]+$/.test(s.trim()))
      .map((s) => s.trim()),
  );

  // The spec is allowed to declare "n/a — ..." sentinel for state_classes_consumed (Tooltip, Progress, etc.).
  const specHasNaSentinel = (spec.state_classes_consumed ?? []).some(
    (s) => typeof s === "string" && /^n\/a\b/i.test(s.trim()),
  );

  const missingInSpec = {
    state_classes: [...sourceStateClasses].filter((s) => !specStateClasses.has(s)),
    tokens: [...sourceTokens].filter((t) => !specTokens.has(t)),
  };
  const staleInSpec = {
    state_classes: specHasNaSentinel
      ? []
      : [...specStateClasses].filter((s) => !sourceStateClasses.has(s)),
    tokens: [...specTokens].filter((t) => !sourceTokens.has(t)),
  };

  if (
    missingInSpec.state_classes.length === 0 &&
    missingInSpec.tokens.length === 0 &&
    staleInSpec.state_classes.length === 0 &&
    staleInSpec.tokens.length === 0
  ) {
    continue;
  }

  violations.push(
    ...applyExceptions({
      dir: compDir,
      ruleId: RULE_ID,
      violations: [
        {
          comp,
          missing: missingInSpec,
          stale: staleInSpec,
          sourceFiles: sourceFiles.map((f) => path.relative(srcRoot, f)),
        },
      ],
      rel: comp,
    }),
  );
}

function* walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      yield* walk(full);
    } else {
      yield full;
    }
  }
}

if (violations.length === 0) {
  ok(`${componentRecords.length} component(s) checked; spec.yaml ↔ source state classes + tokens in sync.`);
  process.exit(0);
}

process.stderr.write(
  `${RED}❌ verify-component-spec-vs-source:${RESET} ${violations.length} component(s) with spec/source drift\n\n`,
);
for (const v of violations) {
  process.stderr.write(`  ${v.comp}:\n`);
  if (v.kind === "spec_parse") {
    process.stderr.write(`    spec.yaml failed to parse: ${v.msg}\n`);
    continue;
  }
  if (v.missing.state_classes.length > 0) {
    process.stderr.write(
      `    state-* classes USED IN SOURCE but missing from spec.state_classes_consumed:\n`,
    );
    for (const s of v.missing.state_classes) process.stderr.write(`      - ${s}\n`);
  }
  if (v.missing.tokens.length > 0) {
    process.stderr.write(
      `    tokens USED IN SOURCE but missing from spec.tokens_consumed:\n`,
    );
    for (const t of v.missing.tokens) process.stderr.write(`      - ${t}\n`);
  }
  if (v.stale.state_classes.length > 0) {
    process.stderr.write(
      `    state-* classes DECLARED IN SPEC but not used in source (stale):\n`,
    );
    for (const s of v.stale.state_classes) process.stderr.write(`      - ${s}\n`);
  }
  if (v.stale.tokens.length > 0) {
    process.stderr.write(
      `    tokens DECLARED IN SPEC but not used in source (stale):\n`,
    );
    for (const t of v.stale.tokens) process.stderr.write(`      - ${t}\n`);
  }
}
process.stderr.write(
  `\n${DIM}Source files scanned: <Component>/*.ts(x) (excluding __stories__/__tests__/__specs__) + the matching shadcn baseline. Update spec.yaml's state_classes_consumed and tokens_consumed lists to match exactly what the source uses, then re-run.${RESET}\n`,
);
process.exit(1);
